create table if not exists public.school_setup_profiles (
  school_id uuid primary key references public.schools(id) on delete cascade,
  education_levels text[] not null default '{}' check (education_levels <@ array['primary','middle_school','high_school']::text[]),
  suggested_classes jsonb not null default '[]'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.school_setup_profiles enable row level security;
create policy school_setup_profile_read_member on public.school_setup_profiles for select to authenticated using (schooly_private.is_approved_school_member(school_id));

create or replace function public.save_school_setup(p_school_id uuid, p_education_levels text[], p_suggested_classes jsonb) returns void language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.school_memberships where school_id = p_school_id and user_id = auth.uid() and role = 'owner') then raise exception 'Seul le propriétaire peut enregistrer la structure initiale'; end if;
  if exists (select 1 from unnest(p_education_levels) value where value not in ('primary','middle_school','high_school')) then raise exception 'Niveau scolaire invalide'; end if;
  insert into public.school_setup_profiles (school_id, education_levels, suggested_classes) values (p_school_id, p_education_levels, p_suggested_classes) on conflict (school_id) do update set education_levels = excluded.education_levels, suggested_classes = excluded.suggested_classes, updated_at = now();
  update public.schools set establishment_type = array_to_string(p_education_levels, ',') where id = p_school_id;
end;
$$;
revoke all on function public.save_school_setup(uuid, text[], jsonb) from public;
grant execute on function public.save_school_setup(uuid, text[], jsonb) to authenticated;
